// Block (composition) — a compact vertical navigation rail (tablet/desktop): a
// column of stacked icon+label destinations. Contract: docs/rules/block-contract.md.
// Reuses NavItem (orientation="vertical") for each item's look + behavior; arranges
// them in a Stack. Owns only layout; mints no tokens. Sits between Sidebar (labelled
// rows) and BottomNav (floating bottom bar). Given a height, the destinations scroll between a
// pinned header and footer, so a short window keeps both in reach.
import type { ReactNode, Ref } from "react";
import { NavItem } from "../components/NavItem";
import { ScrollArea } from "../components/ScrollArea";
import { Stack } from "../layouts/Stack";
import "./NavigationRail.css";

export interface NavigationRailItemBase {
  /** Visible label under the icon. */
  label: string;
  /** Item icon. */
  icon: ReactNode;
  /** Marks the active destination. */
  isCurrent?: boolean;
}

/** Link or button, never both — mirrors NavItem's own mode union so the either/or the JSDoc
    always claimed is enforced at the data layer, not silently resolved in favour of `href`. */
export type NavigationRailItem = NavigationRailItemBase &
  (
    | {
        /** Destination. Present → renders a link. */
        href: string;
        onPress?: never;
      }
    | {
        href?: never;
        /** Press handler — button mode (no `href`). */
        onPress?: () => void;
      }
  );

export interface NavigationRailProps {
  /**
   * Density of every destination, forwarded to each NavItem. `small` is for a compact rail beside
   * dense content; each destination stays 4:3 at both sizes.
   *
   * @default "medium"
   */
  size?: "small" | "medium";
  /**
   * Which part of each destination carries the current, hover and pressed fill, forwarded to each
   * NavItem. `item` fills the whole 4:3 tile; `icon` fills only a square box around the icon and
   * marks the current destination's label below it by ink and weight (a workspace rail's look).
   *
   * @default "item"
   */
  indicator?: "item" | "icon";
  /** Navigation destinations. */
  items: NavigationRailItem[];
  /** Content pinned to the top (e.g. a logo, a workspace switcher or a menu button). */
  header?: ReactNode;
  /** Content pinned to the bottom (e.g. a settings item, an avatar or view toggles). */
  footer?: ReactNode;
  /** Accessible name for the navigation landmark. */
  "aria-label"?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function NavigationRail({
  size = "medium",
  indicator = "item",
  items,
  header,
  footer,
  "aria-label": ariaLabel = "Primary",
  className,
  ref,
}: NavigationRailProps) {
  return (
    <Stack
      as="nav"
      ref={ref}
      direction="column"
      align="center"
      gap="small"
      aria-label={ariaLabel}
      className={className ? `sd-navigationrail ${className}` : "sd-navigationrail"}
    >
      {header && <div className="sd-navigationrail__header">{header}</div>}
      <ScrollArea className="sd-navigationrail__scroll">
      <Stack
        as="ul"
        direction="column"
        align="center"
        gap="2x-small"
        className="sd-navigationrail__items"
      >
        {items.map((item) => (
          <li key={item.href ?? item.label} className="sd-navigationrail__item">
            {item.href != null ? (
              <NavItem
                size={size}
                orientation="vertical"
                indicator={indicator}
                icon={item.icon}
                isCurrent={item.isCurrent}
                href={item.href}
              >
                {item.label}
              </NavItem>
            ) : (
              <NavItem
                size={size}
                orientation="vertical"
                indicator={indicator}
                icon={item.icon}
                isCurrent={item.isCurrent}
                onPress={item.onPress}
              >
                {item.label}
              </NavItem>
            )}
          </li>
        ))}
      </Stack>
      </ScrollArea>
      {footer && <div className="sd-navigationrail__footer">{footer}</div>}
    </Stack>
  );
}

/* NavigationRail.css — .sd-navigationrail (Block)
   Arrangement only: a full-height vertical rail. NavItem owns each item's look;
   this Block places the header / items / footer column. Footer pins to the bottom.
   No look, no tokens. */
/* NO padding at all: the rail is arrangement and owns no paper, so every inset from its
   destinations to a visible edge belongs to whatever it sits in.
   An inset here stacks with the wrapper's: on a Card the two would sum to 20px on the sides against
   28 on the block axis. A Card pads all four sides, so the inset is the wrapper's on every axis,
   not on one. */
/* Given a height by its host, the rail shrinks to it rather than growing past it. */
.sd-navigationrail {
  min-block-size: 0;
}

.sd-navigationrail__header,
.sd-navigationrail__footer {
  flex-shrink: 0;
}

/* The destinations take the room between header and footer and scroll inside it; ScrollArea's
   gutter is compensated, so the items keep the rail's full width. */
.sd-navigationrail__scroll {
  width: 100%;
  flex: 1 1 auto;
  min-block-size: 0;
}

.sd-navigationrail__items {
  width: 100%;
  list-style: none;
  margin: 0;
  padding: 0;
}

/* No destination box here. NavItem owns that box itself, so the rail keeps one shape whatever its
   labels: a stacked item has a definite height summed from its
   own parts and a width that follows at 4:3, at either `size`. A second box here cannot agree with
   it: in aronia the item is 83x62, larger than the 80x60 cell. */

.sd-navigationrail__footer {
  margin-block-start: auto;
}
